import { Link } from 'react-router-dom'
import Button from '@components/ui/Button'

const ResetPassword = () => {
  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 to-sage-50 flex items-center justify-center px-4">
      <div className="max-w-md w-full bg-white rounded-xl shadow-lg p-8">
        <h2 className="text-2xl font-bold text-dusty-900 mb-6">Reset Password</h2>
        <p className="text-dusty-600 mb-4">Enter your new password.</p>
        <input 
          type="password" 
          placeholder="New password"
          className="w-full px-4 py-2 border rounded-lg mb-4"
        />
        <input 
          type="password" 
          placeholder="Confirm password"
          className="w-full px-4 py-2 border rounded-lg mb-4"
        />
        <Button className="w-full mb-4">Reset Password</Button>
        <Link to="/login" className="text-primary-600 hover:text-primary-700 text-sm">
          Back to Login
        </Link>
      </div>
    </div>
  )
}

export default ResetPassword
